import { Fighter } from "./Fighter.vgraph.ts";
import { Knight } from "./Knight.vgraph.ts";
import { Team } from "./Team.vgraph.ts";

export class Game {
  Hero: Fighter | null = null;
  Villain: Fighter | null = null;
  private makeKnight_object: Knight | null = null;
  private makeGoblin_object: Fighter | null = null;
  private loop_stop: boolean = false;
  private loop_index: number = 0;
  private hit_remaining: number = 0;
  private hit_defeated: boolean = false;
  private teamSwitch_selection: Team = Team.Red;
  private wait_pending: boolean = false;

  start(): void {
    // Construct Knight (makeKnight)
    this.makeKnight_object = new Knight();
    this.makeKnight_object.start();
    // Set Hero (setHero)
    this.Hero = this.makeKnight_object;
    // Set Name (nameHero)
    this.Hero!.Name = "Knight";
    // Construct Fighter (makeGoblin)
    this.makeGoblin_object = new Fighter();
    this.makeGoblin_object.start();
    // Set Villain (setVillain)
    this.Villain = this.makeGoblin_object;
    // Set Name (nameVillain)
    this.Villain!.Name = "Goblin";
    // Bind Event to Defeated (bind)
    this.Villain!.Defeated.bind(this, this.onDefeated);
    // For Loop with Break (loop)
    this.loop_stop = false;
    for (this.loop_index = 1; this.loop_index <= 3 && !this.loop_stop; this.loop_index++) {
      // Announce: Print (announce)
      console.log("round");
      console.log(String(this.loop_index));
      // Take Hit (hit)
      ({ remaining: this.hit_remaining, defeated: this.hit_defeated } = this.Villain!.takeHit(this.Hero!.attackPower()));
      // Print (printRemaining)
      console.log(String(this.hit_remaining));
      // Branch (wasDefeated)
      if (this.hit_defeated) {
        // For Loop with Break (loop)
        this.loop_stop = true;
      }
    }
    // Print (victory)
    console.log("victory");
    // Print (printTeam)
    console.log(formatValue(this.Villain!.Stats.team));
    // Switch on Team (teamSwitch)
    this.teamSwitch_selection = this.Villain!.Stats.team;
    if (this.teamSwitch_selection === Team.Red) {
      // Print (red)
      console.log("red team");
      this.run_wait();
    } else if (this.teamSwitch_selection === Team.Blue) {
      // Print (blue)
      console.log("blue team");
      this.run_wait();
    }
  }

  onDefeated(name: string): void {
    // Print (printDefeated)
    console.log(this.string_append(name, " is defeated"));
  }

  private run_wait(): void {
    // Delay (wait)
    if (!this.wait_pending) {
      this.wait_pending = true;
      setTimeout(() => {
        this.wait_pending = false;
        // Print (end)
        console.log("the end");
      }, 0.1 * 1000);
    }
  }

  private string_append(a: string, b: string): string {
    return a + b;
  }
}

function formatValue(value: unknown): string {
  if (value === null || value === undefined) return "";
  if (typeof value === "string") return value;
  if (typeof value === "number" || typeof value === "boolean") return String(value);
  const json = (v: unknown): string | undefined => {
    if (v instanceof Set) return json([...v].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0)));
    if (v instanceof Map) return "{" + [...v].map(([k, x]) => JSON.stringify(String(k)) + ":" + (json(x) ?? "null")).join(",") + "}";
    if (Array.isArray(v)) return "[" + v.map((x) => json(x) ?? "null").join(",") + "]";
    if (v !== null && typeof v === "object" && typeof Object(v).toJSON !== "function") {
      return "{" + Object.entries(v).flatMap(([k, x]) => { const t = json(x); return t === undefined ? [] : [JSON.stringify(k) + ":" + t]; }).join(",") + "}";
    }
    return JSON.stringify(v);
  };
  return json(value) ?? "";
}
